const D = { energy:.6, density:.5, scale:1, speed:1, hue:96, x:.5, y:.72, wander:.6, style:'plate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), DN = cl(P.density,0,1), SC = cl(P.scale,.4,2.2);
const WD = cl(P.wander,0,1), AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;
const gust = .9*Math.sin(T*.61) + .5*Math.sin(T*1.43+1.7) + .32*Math.sin(T*2.29);
const breeze = (.2 + .7*EN)*gust + A.lowmid*.6 + K.pulse*.16*K.intensity;

// ---- the light: two incommensurate rates -> its path NEVER repeats -------
const soil = P.y;
const lightX = tt => (.5 + .46*Math.sin(tt*.083)*Math.cos(tt*.0331*WD + 1.2) + (P.x - .5)*.7)*width;
const lightY = tt => (soil - .28 - .30*(.5 + .5*Math.sin(tt*.0517 + .8))*(.4 + .6*WD))*height;
const lx = lightX(T), ly = lightY(T);

// ---- style ---------------------------------------------------------------
const H = P.hue;
let mode;
if (sty === 'cyanotype') mode = 1; else if (sty === 'xray') mode = 2;
else if (sty === 'schematic') mode = 3; else mode = 0;

// ---- sky + soil ground ---------------------------------------------------
const bgKey = [width,height,sd,sty,H,soil].join('|');
if (!S.g || S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const bw = Math.min(600, Math.max(220, width|0));
  const bh = Math.max(1, Math.round(bw*height/Math.max(1,width)));
  const g = (S.g && S.g.width === bw && S.g.height === bh) ? S.g : createGraphics(bw, bh);
  S.g = g; g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.noStroke();
  const hz = bh*soil;
  for (let y=0;y<bh;y++){ const v = y/Math.max(1,hz);
    if (y < hz) {
      if (mode === 1) g.fill(214, 82 - v*10, 24 + v*10);
      else if (mode === 2) g.fill(198, 44, 13 + v*5);
      else if (mode === 3) g.fill(206, 46, 30 + v*7);
      else g.fill(36 - v*4, 13 + v*7, 76 - v*10);
    } else {
      const w = (y - hz)/Math.max(1, bh - hz);
      if (mode === 1) g.fill(216, 78 - w*8, 15 - w*5);
      else if (mode === 2) g.fill(200, 36, 20 + w*6);
      else if (mode === 3) g.fill(206, 32, 20 - w*5);
      else g.fill(26 - w*4, 42 + w*8, 30 - w*13);
    }
    g.rect(0, y, bw, 1.2); }
  for (let i=0;i<3400;i++){                                 // soil tooth + sky grain
    const y2 = fr(i*7.7+9)*bh;
    g.fill(0, 0, mode===0&&y2>hz ? 40 : 96, y2 > hz ? 7 + fr(i*2.1)*11 : 4 + fr(i*3.3)*5);
    g.rect(fr(i*3.1)*bw, y2, 1.4, 1.4); }
  if (mode === 3) {                                          // blueprint rule
    g.noFill(); g.stroke(190, 20, 88, 9); g.strokeWeight(.7);
    for (let x=0;x<bw;x+=bw*.05) g.line(x, 0, x, bh);
    for (let y=0;y<bh;y+=bw*.05) g.line(0, y, bw, y);
    g.stroke(190, 14, 96, 26); g.strokeWeight(1.1); g.line(0, hz, bw, hz); g.noStroke();
  } else {
    g.fill(mode===1?216:(mode===2?200:24), mode===0?46:30, mode===2?26:12, 34);
    g.rect(0, hz, bw, bh*.008);                              // the soil line
  }
  const dc = g.drawingContext;
  const vg = dc.createRadialGradient(bw*.5, bh*.5, bw*.14, bw*.5, bh*.5, bw*.86);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.42)');
  dc.fillStyle = vg; dc.fillRect(0, 0, bw, bh);
  g.pop();
}

// ---- stems: tissue is laid down at the apex and then RIGID ---------------
// each stem is therefore a frozen graph of where the light has been.
const NMAX = 24, MAXP = 46;
const vdc = i => { let v = 0, den = 1, m = i|0;          // van der Corput: any prefix spreads
  for (let k=0;k<5;k++){ den *= 2; v += (m % 2)/den; m = (m/2)|0; } return v; };
const reseed = (s) => {
  const j = s.id*19.9 + (s.gen = (s.gen||0)+1)*7.7;
  s.bx = .04 + vdc(s.id)*.92 + (fr(j*1.3)-.5)*.026;
  s.pts = [{ x:0, y:0 }];
  s.ang = -Math.PI*.5 + (fr(j*2.1)-.5)*.3;
  s.acc = 0; s.age = 0; s.vig = .68 + fr(j*3.7)*.7;
  s.hj = (fr(j*4.3)-.5)*24; s.ph = fr(j*5.9)*6.28;
  s.life = 26 + fr(j*6.7)*20; s.hold = 8 + fr(j*7.3)*12; s.sen = 10 + fr(j*8.1)*10;
  s.leaf = [];
};
const adv = (s, d, tt) => {
  const LX = lightX(tt), LY = lightY(tt);
  s.age += d;
  if (s.age > s.life + s.hold + s.sen) { reseed(s); return; }
  if (s.age < s.life && s.pts.length < MAXP) {
    s.acc += d*(1.5 + EN*1.4)*(.6 + .8*K.intensity);
    let guard = 0;
    while (s.acc > 1 && s.pts.length < MAXP && guard++ < 5) {
      s.acc -= 1;
      const p = s.pts[s.pts.length-1];
      // auxin migrates to the shaded flank -> that flank elongates -> the apex turns to the light
      const ax = s.bx*width, ay = soil*height;
      const wx = ax + p.x, wy = ay + p.y;
      const toL = Math.atan2(LY - wy, LX - wx);
      let df = toL - s.ang; while (df > Math.PI) df -= 6.2832; while (df < -Math.PI) df += 6.2832;
      const grav = -Math.PI*.5 - s.ang;                      // negative gravitropism keeps it upright
      let dg = grav; while (dg > Math.PI) dg -= 6.2832; while (dg < -Math.PI) dg += 6.2832;
      s.ang += df*(.10 + .26*EN) + dg*.05 + (fr(s.pts.length*3.1 + s.id)-.5)*.07;
      s.ang = cl(s.ang, -Math.PI*.5 - 1.32, -Math.PI*.5 + 1.32);   // it cannot bend past horizontal
      // NOTE: the point is pushed and never touched again — the stem IS the light's history
      const st2 = u*.021*SC*s.vig;
      s.pts.push({ x: p.x + Math.cos(s.ang)*st2, y: p.y + Math.sin(s.ang)*st2 });
      if (s.pts.length % 3 === 0 && s.leaf.length < 7)
        s.leaf.push({ i: s.pts.length-1, sg: (s.pts.length % 6) ? 1 : -1, ph: fr(s.pts.length*2.3+s.id)*6.28 });
    }
  }
  const ph = s.life + s.hold;
  s.fade = s.age > ph ? cl(1 - (s.age-ph)/s.sen, 0, 1) : 1;
  s.dry = s.age > ph ? cl((s.age-ph)/s.sen, 0, 1) : 0;
};
if (!S.st || S.st.length !== NMAX || S.szKey !== width+'x'+height+sd) {
  S.szKey = width+'x'+height+sd; S.st = [];
  for (let i=0;i<NMAX;i++){ const s = { id:i }; reseed(s);
    const w = fr(i*11.3)*52; let tt = T - w;               // replay the light's real past
    for (let q=0;q<Math.round(w*20);q++){ adv(s, 1/20, tt); tt += 1/20; }
    S.st.push(s); }
}
for (let i=0;i<NMAX;i++) adv(S.st[i], dt*SP, T);

// ---- draw ----------------------------------------------------------------
image(S.g, 0, 0, width, height);
const nDraw = Math.max(2, Math.round(4 + DN*20));
const sy = soil*height;
if (mode === 2) blendMode(ADD);
strokeCap(ROUND); strokeJoin(ROUND);

// the sweeping shadows are half the motion in this piece
if (mode !== 3) {
  noStroke();
  for (let n=0;n<nDraw;n++) {
    const s = S.st[n]; if (!s || s.pts.length < 3) continue;
    const bx = s.bx*width;
    const dxl = bx - lx, dyl = sy - ly;
    const hgt = -s.pts[s.pts.length-1].y;
    const sl = cl(dyl / Math.max(1, Math.abs(dyl)) * (dxl/Math.max(u*.05, Math.abs(dyl)))*1.6, -6, 6);
    fill(mode===1 ? 218 : (mode===2 ? 200 : 22), mode===1?70:38, mode===2?30:12, 26*AL*(s.fade==null?1:s.fade));
    beginShape();
    vertex(bx - u*.006*s.vig, sy);
    vertex(bx + sl*hgt*.9, sy + hgt*.06 + u*.004);
    vertex(bx + sl*hgt*.9, sy + hgt*.06 + u*.012);
    vertex(bx + u*.006*s.vig, sy + u*.006);
    endShape(CLOSE);
  }
}

for (let n=0;n<nDraw;n++) {
  const s = S.st[n]; if (!s || !s.pts || s.pts.length < 2) continue;
  const fade = s.fade == null ? 1 : s.fade, dry = s.dry || 0;
  const bx = s.bx*width;
  const hh = ((P.hue + s.hj + dry*24) % 360 + 360) % 360;
  const ss = (58 - dry*30), bb = (40 + dry*14);
  const sw = u*.0055*SC*s.vig;
  const droop = dry*dry;                                     // senescent stems lose turgor and bow
  const ddir = (s.id % 2) ? 1 : -1;
  const PX = [], PY = [];
  for (let i=0;i<s.pts.length;i++){
    const p = s.pts[i], v = i/Math.max(1, s.pts.length-1);
    const dd = droop*v*v;                                    // the bow is worst at the tip
    const wob = breeze*u*.012*v*v*s.vig*(1 + .5*Math.sin(T*1.7 + s.ph));
    PX.push(bx + p.x + ddir*dd*Math.abs(p.y)*.62 + wob);
    PY.push(sy + p.y*(1 - dd*.42));
  }
  noFill();
  if (mode === 1) stroke(214, 12 + dry*8, 94 - dry*20, 88*AL*fade);
  else if (mode === 2) stroke(hh, 45, 76, 30*AL*fade);
  else if (mode === 3) stroke(190, 16, 96, 74*AL*fade);
  else stroke(hh, ss, bb, 88*AL*fade);
  strokeWeight(sw);
  beginShape(); for (let i=0;i<PX.length;i++) vertex(PX[i], PY[i]); endShape();
  if (mode === 0) {                                          // lit flank / shaded flank
    stroke(hh, ss*.5, bb + 30, 46*AL*fade); strokeWeight(sw*.34);
    beginShape();
    for (let i=0;i<PX.length;i++){ const dxl = PX[i]-lx, dyl = PY[i]-ly, dl = Math.max(1e-3, Math.hypot(dxl,dyl));
      vertex(PX[i] - dxl/dl*sw*.3, PY[i] - dyl/dl*sw*.3); }
    endShape();
  }
  // cotyledons / leaves — they track the light too
  for (let q=0;q<s.leaf.length;q++){
    const lf = s.leaf[q], i = Math.min(lf.i, PX.length-1);
    const px2 = PX[i], py2 = PY[i];
    const toL = Math.atan2(ly - py2, lx - px2);
    const fl = Math.sin(T*(2.1 + (lf.ph%1)*1.3) + lf.ph)*(.14 + .4*EN);
    const ang = toL + lf.sg*(.95 + fl) + droop*.6;
    const L = u*.036*SC*s.vig*(1 - dry*.3);
    push(); translate(px2, py2); rotate(ang);
    scale(1, .4 + .6*Math.abs(Math.cos(fl*1.4)));
    if (mode === 1) { noStroke(); fill(214, 6, 97, 86*AL*fade); }
    else if (mode === 2) { noStroke(); fill(hh, 52, 44, 20*AL*fade); }
    else if (mode === 3) { noFill(); stroke(190, 18, 94, 62*AL*fade); strokeWeight(Math.max(.5, sw*.28)); }
    else { noStroke(); fill(hh, ss + 6, bb + 8 - dry*8, 90*AL*fade); }
    beginShape(); vertex(0, 0); bezierVertex(L*.32,-L*.30, L*.8,-L*.24, L, 0);
    bezierVertex(L*.8, L*.24, L*.32, L*.30, 0, 0); endShape(CLOSE);
    pop();
  }
  if (mode === 3) {                                          // schematic: the auxin vector at the apex
    const i = PX.length-1, toL = Math.atan2(ly - PY[i], lx - PX[i]);
    stroke(28, 74, 96, 70*AL*fade); strokeWeight(Math.max(.7, sw*.4));
    line(PX[i], PY[i], PX[i] + Math.cos(toL)*u*.05, PY[i] + Math.sin(toL)*u*.05);
    noStroke(); fill(28, 74, 96, 70*AL*fade);
    ellipse(PX[i] + Math.cos(toL)*u*.05, PY[i] + Math.sin(toL)*u*.05, u*.008, u*.008);
  }
}

// ---- the light itself ----------------------------------------------------
const glow = .8 + .2*Math.sin(T*1.9) + K.pulse*.1*K.intensity + A.treble*.14;
blendMode(mode === 3 ? BLEND : ADD);
noStroke();
if (mode === 3) {
  noFill(); stroke(28, 74, 96, 72*AL); strokeWeight(1.4);
  ellipse(lx, ly, u*.07, u*.07);
  line(lx - u*.05, ly, lx + u*.05, ly); line(lx, ly - u*.05, lx, ly + u*.05);
} else {
  for (let k=10;k>0;k--){
    const r = u*(.02 + k*.028)*(1 + .04*Math.sin(T*.9 + k));
    fill(mode===1 ? 210 : (mode===2 ? 190 : 46), mode===1?18:(mode===2?24:36), 100, (mode===2?2.2:3.4)*glow*AL);
    ellipse(lx, ly, r*2, r*2);
  }
  fill(mode===1 ? 210 : 50, 8, 100, 78*AL*glow); ellipse(lx, ly, u*.038, u*.038);
}
blendMode(BLEND);
